/// A DiagnosticType defines the type of the diagnostic.
///
/// Java: public enum JCDiagnostic.DiagnosticType
#[allow(non_camel_case_types)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum DiagnosticType {
    /// A fragment of an enclosing diagnostic.
    FRAGMENT,
    /// A note: similar to, but less serious than, a warning.
    NOTE,
    /// A warning.
    WARNING,
    /// An error.
    ERROR,
}

impl DiagnosticType {
    /// Java: DiagnosticType.key field (used to build the resource key).
    pub fn key(self) -> &'static str {
        match self {
            DiagnosticType::FRAGMENT => "misc",
            DiagnosticType::NOTE => "note",
            DiagnosticType::WARNING => "warn",
            DiagnosticType::ERROR => "err",
        }
    }
}

/// Flags for diagnostic kinds.
///
/// Java: public enum JCDiagnostic.DiagnosticFlag
#[allow(non_camel_case_types)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum DiagnosticFlag {
    MANDATORY,
    RESOLVE_ERROR,
    SYNTAX,
    RECOVERABLE,
    NON_DEFERRABLE,
    COMPRESSED,
    /// Flag for diagnostics that were reported through API methods.
    API,
    /// Flag for not-supported-in-source-X errors.
    SOURCE_LEVEL,
}

/// A DiagnosticPosition provides information about the positions in a file that
/// gave rise to a diagnostic. It always defines a "preferred" position that most
/// accurately defines the location of the diagnostic, it may also provide a
/// related tree node that spans that location.
///
/// Java: public static interface JCDiagnostic.DiagnosticPosition
pub trait DiagnosticPosition {
    /// Gets the tree node, if any, to which the diagnostic applies.
    ///
    /// PORTING_RULES: Java JCTree -> arena TreeId; null -> None.
    fn get_tree(&self) -> Option<TreeId>;

    /// If there is a tree node, get the start position of the tree node.
    /// Otherwise, just returns the same as getPreferredPosition().
    fn get_start_position(&self) -> i32;

    /// Get the position within the file that most accurately defines the
    /// location for the diagnostic.
    fn get_preferred_position(&self) -> i32;

    /// If there is a tree node, and if endPositions are available, get the end
    /// position of the tree node. Otherwise, just returns the same as
    /// getPreferredPosition().
    fn get_end_position(&self, end_pos_table: Option<&dyn EndPosTable>) -> i32;
}

/// A DiagnosticPosition that simply identifies a position, but no related tree
/// node, as the location for a diagnostic. Used for scanner and parser
/// diagnostics.
///
/// Java: public static class JCDiagnostic.SimpleDiagnosticPosition
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SimpleDiagnosticPosition {
    pos: i32,
}

impl SimpleDiagnosticPosition {
    /// Java: public SimpleDiagnosticPosition(int pos)
    pub fn new(pos: i32) -> SimpleDiagnosticPosition {
        SimpleDiagnosticPosition { pos }
    }
}

impl DiagnosticPosition for SimpleDiagnosticPosition {
    fn get_tree(&self) -> Option<TreeId> {
        None
    }

    fn get_start_position(&self) -> i32 {
        self.pos
    }

    fn get_preferred_position(&self) -> i32 {
        self.pos
    }

    fn get_end_position(&self, _end_pos_table: Option<&dyn EndPosTable>) -> i32 {
        self.pos
    }
}

/// Java diagnostic argument (an element of JCDiagnostic.DiagnosticInfo.args,
/// which is a Java Object[]). ADR 0002 revision C: the original object identity
/// and type are preserved so formatters can inspect the concrete type.
pub type DiagnosticArg = Rc<dyn Any>;

/// Helper to box a Java object literal as a diagnostic argument.
pub fn diagnostic_arg<T: Any>(value: T) -> DiagnosticArg {
    Rc::new(value)
}

/// A diagnostic key object encapsulates basic properties of a diagnostic, such
/// as the resource key, the arguments and the kind associated with the
/// diagnostic object.
///
/// Java: public static abstract class JCDiagnostic.DiagnosticInfo
#[derive(Clone)]
pub struct DiagnosticInfo {
    /// The diagnostic kind (i.e. error).
    pub(crate) type_: DiagnosticType,
    /// The diagnostic prefix (i.e. "javac"); used to compute the full resource
    /// key.
    pub(crate) prefix: String,
    /// The diagnostic code (i.e. "cannot.resolve.sym"); together with prefix it
    /// forms the full resource key.
    pub(crate) code: String,
    /// The diagnostic arguments.
    pub(crate) args: Vec<DiagnosticArg>,
}

impl fmt::Debug for DiagnosticInfo {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("DiagnosticInfo")
            .field("type", &self.type_)
            .field("prefix", &self.prefix)
            .field("code", &self.code)
            .field("args_len", &self.args.len())
            .finish()
    }
}

impl DiagnosticInfo {
    fn new(
        type_: DiagnosticType,
        prefix: &str,
        code: &str,
        args: Vec<DiagnosticArg>,
    ) -> DiagnosticInfo {
        DiagnosticInfo {
            type_,
            prefix: prefix.to_string(),
            code: code.to_string(),
            args,
        }
    }

    /// Compute the resource key.
    pub fn key(&self) -> String {
        format!("{}.{}.{}", self.prefix, self.type_.key(), self.code)
    }

    /// Static factory method; build a custom diagnostic key using the given
    /// kind, prefix, code and args.
    ///
    /// PORTING_RULES: the upstream returns one of the four DiagnosticInfo
    /// subclasses; the adapter returns the base DiagnosticInfo (the type field
    /// carries the kind), the four newtypes are used at the Factory key
    /// boundary.
    pub fn of(
        type_: DiagnosticType,
        prefix: &str,
        code: &str,
        args: Vec<DiagnosticArg>,
    ) -> DiagnosticInfo {
        DiagnosticInfo::new(type_, prefix, code, args)
    }

    /// Returns the code for this diagnostic info.
    pub fn get_code(&self) -> &str {
        &self.code
    }

    /// Returns the arguments for this diagnostic info.
    pub fn get_args(&self) -> &[DiagnosticArg] {
        &self.args
    }

    /// Java: public void setArgs(Object[] args)
    pub fn set_args(&mut self, args: Vec<DiagnosticArg>) {
        self.args = args;
    }

    /// The diagnostic kind (Java: package-private field type).
    pub fn get_type(&self) -> DiagnosticType {
        self.type_
    }

    /// The diagnostic prefix (Java: package-private field prefix).
    pub fn get_prefix(&self) -> &str {
        &self.prefix
    }
}

