macro_rules! info_key_type {
    ($name:ident, $contract_name:ident, $kind:ident) => {
        impl $name {
            /// Java: public $name(String prefix, String key, Object... args)
            pub fn new(prefix: &str, code: &str, args: Vec<DiagnosticArg>) -> $name {
                $name(DiagnosticInfo::new(DiagnosticType::$kind, prefix, code, args))
            }

            /// The wrapped diagnostic info.
            pub fn info(&self) -> &DiagnosticInfo {
                &self.0
            }

            /// Take the wrapped diagnostic info.
            pub fn into_info(self) -> DiagnosticInfo {
                self.0
            }
        }

        impl From<contract::$contract_name> for $name {
            fn from(value: contract::$contract_name) -> $name {
                let info = value.info();
                $name(DiagnosticInfo::new(
                    DiagnosticType::$kind,
                    info.prefix,
                    info.code,
                    contract_args_to_args(&info.args),
                ))
            }
        }
    };
}

info_key_type!(Error, ErrorInfo, ERROR);
info_key_type!(Warning, WarningInfo, WARNING);
info_key_type!(Note, NoteInfo, NOTE);
info_key_type!(Fragment, FragmentInfo, FRAGMENT);

/// The pre-P4 contract feeding the resources-generated accessors: the contract argument is currently placeholder Display
/// text, kept as a JavaString argument (ADR 0002 revision C: after the xtask contract replacement it becomes a real object and
/// this function is then removed).
pub(crate) fn contract_args_to_args(args: &[contract::DiagnosticArg]) -> Vec<DiagnosticArg> {
    args.iter()
        .map(|arg| match arg {
            contract::DiagnosticArg::Text(text) => {
                Rc::new(JavaString::from(text.as_str())) as DiagnosticArg
            }
            contract::DiagnosticArg::JCDiagnostic(diag) => {
                // Java: a JCDiagnostic is itself an Object[] element — keep the
                // nested diagnostic object (downcastable from Rc<dyn Any>).
                Rc::clone(diag) as DiagnosticArg
            }
        })
        .collect()
}

/// Java: Lint.LintCategory
///
/// PORTING_RULES: the Lint ported the real class in code/lint.rs; the
/// temporary dependency holder of the JCDiagnostic step is replaced by this
/// re-export (registered section 9).
pub use crate::code::lint::LintCategory;

/// An abstraction of a diagnostic message generated by the compiler.
///
/// Java: public class JCDiagnostic implements Diagnostic<JavaFileObject>
#[derive(Clone)]
pub struct JCDiagnostic {
    /// Java: private final DiagnosticSource source (null -> None).
    source: Option<Rc<DiagnosticSource>>,
    /// Java: private final DiagnosticPosition position (null -> None).
    position: Option<Rc<dyn DiagnosticPosition>>,
    /// Java: private final DiagnosticInfo diagnosticInfo
    diagnostic_info: DiagnosticInfo,
    /// Java: private final Set<DiagnosticFlag> flags (EnumSet -> Vec, Porting rules).
    flags: Vec<DiagnosticFlag>,
    /// Java: private final LintCategory lintCategory (null -> None)
    lint_category: Option<LintCategory>,
    /// Java: private DiagnosticFormatter<JCDiagnostic> defaultFormatter
    default_formatter: Option<Rc<dyn DiagnosticFormatter<JCDiagnostic>>>,
    /// Java: MultilineDiagnostic.subdiagnostics (the upstream subclass is
    /// expressed by this field; empty for single-line diagnostics).
    subdiagnostics: List<JCDiagnostic>,
}

impl JCDiagnostic {
    /// Create a diagnostic object.
    ///
    /// Java: protected JCDiagnostic(DiagnosticFormatter, DiagnosticInfo,
    /// LintCategory, Set<DiagnosticFlag>, DiagnosticSource, DiagnosticPosition)
    fn new(
        formatter: Option<Rc<dyn DiagnosticFormatter<JCDiagnostic>>>,
        diagnostic_info: DiagnosticInfo,
        lint_category: Option<LintCategory>,
        flags: Vec<DiagnosticFlag>,
        source: Option<Rc<DiagnosticSource>>,
        position: Option<Rc<dyn DiagnosticPosition>>,
    ) -> JCDiagnostic {
        // Java: if (source == null && pos != null &&
        // pos.getPreferredPosition() != Position.NOPOS)
        // throw new IllegalArgumentException();
        if source.is_none()
            && let Some(position) = &position
            && position.get_preferred_position() != NOPOS
        {
            panic!("IllegalArgumentException: source is null with a non-NOPOS position");
        }
        JCDiagnostic {
            source,
            position,
            diagnostic_info,
            flags,
            lint_category,
            default_formatter: formatter,
            subdiagnostics: List::nil(),
        }
    }

    /// Get the type of this diagnostic.
    pub fn get_type(&self) -> DiagnosticType {
        self.diagnostic_info.type_
    }

    /// Get the subdiagnostic list.
    pub fn get_subdiagnostics(&self) -> List<JCDiagnostic> {
        self.subdiagnostics.clone()
    }

    /// Java: public boolean isMultiline()
    pub fn is_multiline(&self) -> bool {
        !self.subdiagnostics.is_empty()
    }

    /// Check whether or not this diagnostic is required to be shown.
    pub fn is_mandatory(&self) -> bool {
        self.flags.contains(&DiagnosticFlag::MANDATORY)
    }

    /// Check whether this diagnostic has an associated lint category.
    pub fn has_lint_category(&self) -> bool {
        self.lint_category.is_some()
    }

    /// Get the associated lint category, or None if none.
    pub fn get_lint_category(&self) -> Option<&LintCategory> {
        self.lint_category.as_ref()
    }

    /// The diagnostic info object (Java: package-private field).
    pub fn get_diagnostic_info(&self) -> &DiagnosticInfo {
        &self.diagnostic_info
    }

    /// Java: protected int getIntStartPosition()
    pub fn get_int_start_position(&self) -> i32 {
        match &self.position {
            None => NOPOS,
            Some(position) => position.get_start_position(),
        }
    }

    /// Java: protected int getIntPosition()
    pub fn get_int_position(&self) -> i32 {
        match &self.position {
            None => NOPOS,
            Some(position) => position.get_preferred_position(),
        }
    }

    /// Java: protected int getIntEndPosition()
    pub fn get_int_end_position(&self) -> i32 {
        let Some(position) = &self.position else {
            return NOPOS;
        };
        let end_pos_table = self
            .source
            .as_ref()
            .and_then(|source| source.get_end_pos_table());
        match end_pos_table {
            Some(table) => position.get_end_position(Some(&*table.borrow())),
            None => position.get_end_position(None),
        }
    }

    /// Java: public long getStartPosition()
    pub fn get_start_position(&self) -> i64 {
        self.get_int_start_position() as i64
    }

    /// Java: public long getPosition()
    pub fn get_position(&self) -> i64 {
        self.get_int_position() as i64
    }

    /// Java: public long getEndPosition()
    pub fn get_end_position(&self) -> i64 {
        self.get_int_end_position() as i64
    }

    /// Java: public DiagnosticPosition getDiagnosticPosition()
    pub fn get_diagnostic_position(&self) -> Option<Rc<dyn DiagnosticPosition>> {
        self.position.clone()
    }

    /// Java: public JavaFileObject getSource()
    pub fn get_source(&self) -> Option<Rc<dyn javac_tools::tools::java_file_object::JavaFileObject>> {
        self.source
            .as_ref()
            .and_then(|source| source.get_file())
    }

    /// Java: public DiagnosticSource getDiagnosticSource()
    pub fn get_diagnostic_source(&self) -> Option<Rc<DiagnosticSource>> {
        self.source.clone()
    }

    /// Java: public long getLineNumber()
    ///
    /// PORTING_RULES: the upstream SourcePosition computes line and column from
    /// the DiagnosticSource; the Rust port computes them on demand (no lazy
    /// cache, registered in the module doc).
    pub fn get_line_number(&self) -> i64 {
        match (&self.position, &self.source) {
            (None, _) | (_, None) => -1,
            (Some(position), Some(source)) => {
                let pos = position.get_preferred_position();
                if pos == NOPOS {
                    -1
                } else {
                    source.get_line_number(pos) as i64
                }
            }
        }
    }

    /// Java: public long getColumnNumber()
    pub fn get_column_number(&self) -> i64 {
        match (&self.position, &self.source) {
            (None, _) | (_, None) => -1,
            (Some(position), Some(source)) => {
                let pos = position.get_preferred_position();
                if pos == NOPOS {
                    -1
                } else {
                    // Java: source.getColumnNumber(n, true)
                    source.get_column_number(pos, true) as i64
                }
            }
        }
    }

    /// Get the arguments to be included in the text of the diagnostic.
    pub fn get_args(&self) -> &[DiagnosticArg] {
        self.diagnostic_info.get_args()
    }

    /// Java: public String getPrefix()
    pub fn get_prefix(&self) -> String {
        self.get_prefix_for(self.diagnostic_info.type_)
    }

    /// Java: public String getPrefix(DiagnosticType dt)
    pub fn get_prefix_for(&self, dt: DiagnosticType) -> String {
        let _ = dt;
        self.formatter().format_kind(self, &Locale::default_locale())
    }

    fn formatter(&self) -> &dyn DiagnosticFormatter<JCDiagnostic> {
        match &self.default_formatter {
            Some(formatter) => formatter.as_ref(),
            None => panic!(
                "diagnostic has no formatter (use Factory::new or Factory::new_with_formatter)"
            ),
        }
    }

    /// The formatter used by this diagnostic, if one was injected.
    pub fn get_formatter(&self) -> Option<&dyn DiagnosticFormatter<JCDiagnostic>> {
        self.default_formatter.as_deref()
    }

    /// Format the diagnostic message for the given locale tag (None = default).
    ///
    /// Java: public String getMessage(Locale locale)
    pub fn get_message(&self, locale: Option<&JavaString>) -> JavaString {
        self.format_message_localized(locale)
    }

    fn format_message_localized(&self, locale: Option<&JavaString>) -> JavaString {
        let locale = match locale {
            Some(tag) => Locale::new(tag.to_string_lossy()),
            None => Locale::default_locale(),
        };
        JavaString::from(self.formatter().format_message(self, &locale).as_str())
    }

    /// Return the standard presentation of this diagnostic.
    ///
    /// Java: public String toString() { return defaultFormatter.format(this,
    /// Locale.getDefault()); }
    pub fn format_diagnostic(&self) -> String {
        self.formatter().format(self, None)
    }

    /// Java: public void setFlag(DiagnosticFlag flag)
    pub fn set_flag(&mut self, flag: DiagnosticFlag) {
        if !self.flags.contains(&flag) {
            self.flags.push(flag);
        }
        if self.diagnostic_info.type_ == DiagnosticType::ERROR {
            match flag {
                DiagnosticFlag::SYNTAX => {
                    self.flags.retain(|f| *f != DiagnosticFlag::RECOVERABLE);
                }
                DiagnosticFlag::RESOLVE_ERROR => {
                    if !self.flags.contains(&DiagnosticFlag::RECOVERABLE) {
                        self.flags.push(DiagnosticFlag::RECOVERABLE);
                    }
                }
                _ => {}
            }
        }
    }

    /// Java: public boolean isFlagSet(DiagnosticFlag flag)
    pub fn is_flag_set(&self, flag: DiagnosticFlag) -> bool {
        self.flags.contains(&flag)
    }

    /// The Java diagnostic kind (javax.tools.Diagnostic.Kind).
    ///
    /// Java: public Diagnostic.Kind getKind()
    pub fn get_kind(&self) -> DiagnosticKind {
        match self.diagnostic_info.type_ {
            DiagnosticType::NOTE => DiagnosticKind::NOTE,
            DiagnosticType::WARNING => {
                if self.flags.contains(&DiagnosticFlag::MANDATORY) {
                    DiagnosticKind::MANDATORY_WARNING
                } else {
                    DiagnosticKind::WARNING
                }
            }
            DiagnosticType::ERROR => DiagnosticKind::ERROR,
            _ => DiagnosticKind::OTHER,
        }
    }

    fn get_code_java_string(&self) -> JavaString {
        JavaString::from(self.diagnostic_info.key().as_str())
    }

    /// Java: public String getCode() { return diagnosticInfo.key(); }
    pub fn get_code_string(&self) -> String {
        self.diagnostic_info.key()
    }
}

impl fmt::Display for JCDiagnostic {
    /// Java: public String toString()
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.format_diagnostic())
    }
}

impl fmt::Debug for JCDiagnostic {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("JCDiagnostic")
            .field("diagnostic_info", &self.diagnostic_info)
            .field("flags", &self.flags)
            .field("lint_category", &self.lint_category)
            .finish()
    }
}

impl Diagnostic<Rc<dyn JavaFileObject>> for JCDiagnostic {
    fn get_kind(&self) -> DiagnosticKind {
        JCDiagnostic::get_kind(self)
    }

    /// Java: Diagnostic.getSource(): the source's file, or null when no source
    /// was attached (JCDiagnostic.java getSource).
    fn get_source(&self) -> Option<Rc<dyn JavaFileObject>> {
        self.source.as_ref().and_then(|source| source.get_file())
    }

    fn get_position(&self) -> i64 {
        JCDiagnostic::get_position(self)
    }

    fn get_start_position(&self) -> i64 {
        JCDiagnostic::get_start_position(self)
    }

    fn get_end_position(&self) -> i64 {
        JCDiagnostic::get_end_position(self)
    }

    fn get_line_number(&self) -> i64 {
        JCDiagnostic::get_line_number(self)
    }

    fn get_column_number(&self) -> i64 {
        JCDiagnostic::get_column_number(self)
    }

    fn get_code(&self) -> Option<JavaString> {
        Some(self.get_code_java_string())
    }

    fn get_message(&self, locale: Option<&JavaString>) -> JavaString {
        self.format_message_localized(locale)
    }
}

/// A diagnostic that has subdiagnostics and is displayed as multiple lines.
///
/// Java: public static class JCDiagnostic.MultilineDiagnostic extends JCDiagnostic
///
/// PORTING_RULES: the upstream subclass is expressed by composition (the inner
/// diagnostic keeps every JCDiagnostic method) plus the overridden methods
/// (getSubdiagnostics / isMultiline).
#[derive(Clone, Debug)]
pub struct MultilineDiagnostic {
    inner: JCDiagnostic,
    subdiagnostics: List<JCDiagnostic>,
}

impl MultilineDiagnostic {
    /// Java: public MultilineDiagnostic(JCDiagnostic other,
    /// List<JCDiagnostic> subdiagnostics)
    pub fn new(other: &JCDiagnostic, subdiagnostics: List<JCDiagnostic>) -> MultilineDiagnostic {
        MultilineDiagnostic {
            inner: JCDiagnostic {
                source: other.source.clone(),
                position: other.position.clone(),
                diagnostic_info: other.diagnostic_info.clone(),
                flags: other.flags.clone(),
                lint_category: other.get_lint_category().cloned(),
                default_formatter: other.default_formatter.clone(),
                subdiagnostics: subdiagnostics.clone(),
            },
            subdiagnostics,
        }
    }

    /// Java: public List<JCDiagnostic> getSubdiagnostics()
    pub fn get_subdiagnostics(&self) -> List<JCDiagnostic> {
        self.subdiagnostics.clone()
    }

    /// Java: public boolean isMultiline() { return true; }
    pub fn is_multiline(&self) -> bool {
        true
    }

    /// The underlying JCDiagnostic (the upstream superclass part).
    pub fn as_diagnostic(&self) -> &JCDiagnostic {
        &self.inner
    }
}

/// A factory for creating diagnostic objects.
///
/// Java: public static class JCDiagnostic.Factory
pub struct Factory {
    /// Java: DiagnosticFormatter<JCDiagnostic> formatter
    formatter: Option<Rc<dyn DiagnosticFormatter<JCDiagnostic>>>,
    /// Java: final String prefix
    prefix: String,
    /// Java: final Set<DiagnosticFlag> defaultErrorFlags (EnumSet -> Vec, Porting rules)
    default_error_flags: Vec<DiagnosticFlag>,
}

impl Factory {
    /// Get the Factory instance for this context.
    ///
    /// Java: public static Factory instance(Context context)
    ///
    /// REGISTERED: the upstream protected Factory(Context) initializes Options
    /// (onlySyntaxErrorsUnrecoverable) and registers an option listener; the
    /// Options instance is ported, but the Factory field/listener hook is not
    /// wired, so instance() only creates/registers the factory.
    pub fn instance(context: &mut Context) -> Rc<Factory> {
        if let Some(instance) = context.get::<Factory>() {
            return instance;
        }
        let messages = JavacMessages::instance(context);
        let instance = Rc::new(Factory::new(messages, "compiler"));
        context.put(Rc::clone(&instance));
        instance
    }

    /// Create a new diagnostic factory.
    ///
    /// Java: public Factory(JavacMessages messages, String prefix)
    pub fn new(messages: Rc<JavacMessages>, prefix: &str) -> Factory {
        let formatter: Rc<dyn DiagnosticFormatter<JCDiagnostic>> =
            Rc::new(BasicDiagnosticFormatter::new(Rc::clone(&messages)));
        Factory {
            formatter: Some(formatter),
            prefix: prefix.to_string(),
            default_error_flags: vec![DiagnosticFlag::MANDATORY],
        }
    }

    /// Adapter constructor: create the factory with an explicit formatter.
    pub fn new_with_formatter(
        messages: Rc<JavacMessages>,
        prefix: &str,
        formatter: Rc<dyn DiagnosticFormatter<JCDiagnostic>>,
    ) -> Factory {
        let _ = messages;
        Factory {
            formatter: Some(formatter),
            prefix: prefix.to_string(),
            default_error_flags: vec![DiagnosticFlag::MANDATORY],
        }
    }

    /// The factory prefix (Java: package-private field prefix).
    pub fn get_prefix(&self) -> &str {
        &self.prefix
    }

    /// Create a new diagnostic with the given key and flags.
    ///
    /// Java: public JCDiagnostic create(LintCategory lc, Set<DiagnosticFlag>
    /// flags, DiagnosticSource source, DiagnosticPosition pos,
    /// DiagnosticInfo diagnosticInfo)
    fn create_internal(
        &self,
        lc: Option<LintCategory>,
        flags: Vec<DiagnosticFlag>,
        source: Option<Rc<DiagnosticSource>>,
        pos: Option<Rc<dyn DiagnosticPosition>>,
        diagnostic_info: DiagnosticInfo,
    ) -> JCDiagnostic {
        JCDiagnostic::new(
            self.formatter.clone(),
            self.normalize(diagnostic_info),
            lc,
            flags,
            source,
            pos,
        )
    }

    /// Replace all nested FragmentKey with full-blown JCDiagnostic objects.
    ///
    /// Java: DiagnosticInfo normalize(DiagnosticInfo diagnosticInfo)
    fn normalize(&self, diagnostic_info: DiagnosticInfo) -> DiagnosticInfo {
        let args: Vec<DiagnosticArg> = diagnostic_info
            .get_args()
            .iter()
            .map(|arg| match arg.downcast_ref::<Fragment>() {
                Some(fragment) => Rc::new(self.fragment(fragment.clone())) as DiagnosticArg,
                None => Rc::clone(arg),
            })
            .collect();
        DiagnosticInfo::new(
            diagnostic_info.type_,
            &diagnostic_info.prefix,
            &diagnostic_info.code,
            args,
        )
    }

    /// Create an error diagnostic.
    ///
    /// Java: public JCDiagnostic error(DiagnosticFlag flag, DiagnosticSource
    /// source, DiagnosticPosition pos, Error errorKey)
    pub fn error(
        &self,
        flag: Option<DiagnosticFlag>,
        source: Option<Rc<DiagnosticSource>>,
        pos: Option<Rc<dyn DiagnosticPosition>>,
        error_key: Error,
    ) -> JCDiagnostic {
        let mut diag = self.create_internal(
            None,
            self.default_error_flags.clone(),
            source,
            pos,
            error_key.into_info(),
        );
        if let Some(flag) = flag {
            diag.set_flag(flag);
        }
        diag
    }

    /// Create a warning diagnostic that will not be hidden by the -nowarn or
    /// -Xlint:none options.
    ///
    /// Java: public JCDiagnostic mandatoryWarning(LintCategory lc,
    /// DiagnosticSource source, DiagnosticPosition pos, Warning warningKey)
    pub fn mandatory_warning(
        &self,
        lc: Option<LintCategory>,
        source: Option<Rc<DiagnosticSource>>,
        pos: Option<Rc<dyn DiagnosticPosition>>,
        warning_key: Warning,
    ) -> JCDiagnostic {
        self.create_internal(
            lc,
            vec![DiagnosticFlag::MANDATORY],
            source,
            pos,
            warning_key.into_info(),
        )
    }

    /// Create a warning diagnostic.
    ///
    /// Java: public JCDiagnostic warning(LintCategory lc, DiagnosticSource
    /// source, DiagnosticPosition pos, Warning warningKey)
    pub fn warning(
        &self,
        lc: Option<LintCategory>,
        source: Option<Rc<DiagnosticSource>>,
        pos: Option<Rc<dyn DiagnosticPosition>>,
        warning_key: Warning,
    ) -> JCDiagnostic {
        self.create_internal(lc, Vec::new(), source, pos, warning_key.into_info())
    }

    /// Create a note diagnostic that will not be hidden by the -nowarn or
    /// -Xlint:none options.
    ///
    /// Java: public JCDiagnostic mandatoryNote(DiagnosticSource source,
    /// Note noteKey)
    pub fn mandatory_note(
        &self,
        source: Option<Rc<DiagnosticSource>>,
        note_key: Note,
    ) -> JCDiagnostic {
        self.create_internal(
            None,
            vec![DiagnosticFlag::MANDATORY],
            source,
            None,
            note_key.into_info(),
        )
    }

    /// Create a note diagnostic.
    ///
    /// Java: public JCDiagnostic note(DiagnosticSource source,
    /// DiagnosticPosition pos, Note noteKey)
    pub fn note(
        &self,
        source: Option<Rc<DiagnosticSource>>,
        pos: Option<Rc<dyn DiagnosticPosition>>,
        note_key: Note,
    ) -> JCDiagnostic {
        self.create_internal(None, Vec::new(), source, pos, note_key.into_info())
    }

    /// Create a fragment diagnostic, for use as an argument in other
    /// diagnostics.
    ///
    /// Java: public JCDiagnostic fragment(Fragment fragmentKey)
    pub fn fragment(&self, fragment_key: Fragment) -> JCDiagnostic {
        self.create_internal(None, Vec::new(), None, None, fragment_key.into_info())
    }

    /// Create a new diagnostic of the given kind, which is not mandatory and
    /// which has no lint category.
    ///
    /// Java: public JCDiagnostic create(DiagnosticType kind, DiagnosticSource
    /// source, DiagnosticPosition pos, String key, Object... args)
    pub fn create(
        &self,
        kind: DiagnosticType,
        source: Option<Rc<DiagnosticSource>>,
        pos: Option<Rc<dyn DiagnosticPosition>>,
        key: &str,
        args: Vec<DiagnosticArg>,
    ) -> JCDiagnostic {
        self.create_internal(
            None,
            Vec::new(),
            source,
            pos,
            DiagnosticInfo::of(kind, &self.prefix, key, args),
        )
    }

    /// Create a new diagnostic of the given kind with explicit lint category and
    /// flags.
    ///
    /// Java: public JCDiagnostic create(DiagnosticType kind, LintCategory lc,
    /// Set<DiagnosticFlag> flags, DiagnosticSource source, DiagnosticPosition
    /// pos, String key, Object... args)
    // The 8-parameter signature is the upstream create(DiagnosticType,
    // LintCategory, Set<DiagnosticFlag>, DiagnosticSource, DiagnosticPosition,
    // String, Object...) method; the lint allow keeps the 1:1 signature
    // (PORTING_RULES section 9).
    #[allow(clippy::too_many_arguments)]
    pub fn create_with_flags(
        &self,
        kind: DiagnosticType,
        lc: Option<LintCategory>,
        flags: Vec<DiagnosticFlag>,
        source: Option<Rc<DiagnosticSource>>,
        pos: Option<Rc<dyn DiagnosticPosition>>,
        key: &str,
        args: Vec<DiagnosticArg>,
    ) -> JCDiagnostic {
        self.create_internal(
            lc,
            flags,
            source,
            pos,
            DiagnosticInfo::of(kind, &self.prefix, key, args),
        )
    }

    /// Create a new diagnostic with the given diagnostic key.
    ///
    /// Java: public JCDiagnostic create(LintCategory lc, Set<DiagnosticFlag>
    /// flags, DiagnosticSource source, DiagnosticPosition pos,
    /// DiagnosticInfo diagnosticInfo)
    pub fn create_info(
        &self,
        lc: Option<LintCategory>,
        flags: Vec<DiagnosticFlag>,
        source: Option<Rc<DiagnosticSource>>,
        pos: Option<Rc<dyn DiagnosticPosition>>,
        diagnostic_info: DiagnosticInfo,
    ) -> JCDiagnostic {
        self.create_internal(lc, flags, source, pos, diagnostic_info)
    }

    /// Create a new error key.
    ///
    /// Java: public Error errorKey(String code, Object... args)
    pub fn error_key(&self, code: &str, args: Vec<DiagnosticArg>) -> Error {
        Error(DiagnosticInfo::new(DiagnosticType::ERROR, &self.prefix, code, args))
    }

    /// Create a new warning key.
    ///
    /// Java: Warning warningKey(String code, Object... args)
    pub fn warning_key(&self, code: &str, args: Vec<DiagnosticArg>) -> Warning {
        Warning(DiagnosticInfo::new(DiagnosticType::WARNING, &self.prefix, code, args))
    }

    /// Create a new note key.
    ///
    /// Java: public Note noteKey(String code, Object... args)
    pub fn note_key(&self, code: &str, args: Vec<DiagnosticArg>) -> Note {
        Note(DiagnosticInfo::new(DiagnosticType::NOTE, &self.prefix, code, args))
    }

    /// Create a new fragment key.
    ///
    /// Java: Fragment fragmentKey(String code, Object... args)
    pub fn fragment_key(&self, code: &str, args: Vec<DiagnosticArg>) -> Fragment {
        Fragment(DiagnosticInfo::new(
            DiagnosticType::FRAGMENT,
            &self.prefix,
            code,
            args,
        ))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::api::diagnostic_formatter::{
        Configuration, DiagnosticPart, DiagnosticFormatter, MultilineLimit, PositionKind,
    };
    use crate::resources::compiler_properties::errors as compiler_errors;
    use crate::tree::end_pos_table::EndPosTable;

    fn tag(text: &str) -> JavaString {
        JavaString::from(text)
    }

    fn string_arg(text: &str) -> DiagnosticArg {
        Rc::new(JavaString::from(text)) as DiagnosticArg
    }

    fn java_string_of(arg: &DiagnosticArg) -> Option<String> {
        arg.downcast_ref::<JavaString>()
            .map(|value| value.to_string_lossy())
    }

    /// A DiagnosticPosition that has a related tree id and records the
    /// EndPosTable passed to getEndPosition.
    struct TreeDiagnosticPosition {
        tree: TreeId,
        start: i32,
        preferred: i32,
        end: i32,
    }

    impl DiagnosticPosition for TreeDiagnosticPosition {
        fn get_tree(&self) -> Option<TreeId> {
            Some(self.tree)
        }

        fn get_start_position(&self) -> i32 {
            self.start
        }

        fn get_preferred_position(&self) -> i32 {
            self.preferred
        }

        fn get_end_position(&self, end_pos_table: Option<&dyn EndPosTable>) -> i32 {
            match end_pos_table {
                None => self.preferred,
                Some(_) => self.end,
            }
        }
    }

    struct MapEndPosTable;
    impl EndPosTable for MapEndPosTable {
        fn get_end_pos(&self, _tree: TreeId) -> i32 {
            NOPOS
        }

        fn store_end(&mut self, _tree: TreeId, _end_pos: i32) {}

        fn replace_tree(&mut self, _old_tree: TreeId, _new_tree: TreeId) -> i32 {
            NOPOS
        }
    }

    #[derive(Default)]
    struct TestConfiguration {
        visible: Vec<DiagnosticPart>,
        depth: i32,
        length: i32,
    }

    impl Configuration for TestConfiguration {
        fn set_visible(&mut self, visible_parts: &[DiagnosticPart]) {
            self.visible = visible_parts.to_vec();
        }

        fn get_visible(&self) -> Vec<DiagnosticPart> {
            self.visible.clone()
        }

        fn set_multiline_limit(&mut self, limit: MultilineLimit, value: i32) {
            match limit {
                MultilineLimit::Depth => self.depth = value,
                MultilineLimit::Length => self.length = value,
            }
        }

        fn get_multiline_limit(&self, limit: MultilineLimit) -> i32 {
            match limit {
                MultilineLimit::Depth => self.depth,
                MultilineLimit::Length => self.length,
            }
        }
    }

    /// Formats the message with the ported JavacMessages chain (which applies
    /// the ported MessageFormat adapter) and a minimal kind/source/position
    /// rendering.
    struct MessagesFormatter {
        messages: Rc<JavacMessages>,
        configuration: TestConfiguration,
    }

    impl MessagesFormatter {
        fn new(messages: Rc<JavacMessages>) -> MessagesFormatter {
            MessagesFormatter {
                messages,
                configuration: TestConfiguration::default(),
            }
        }
    }

    impl DiagnosticFormatter<JCDiagnostic> for MessagesFormatter {
        fn display_source(&self, _diag: &JCDiagnostic) -> bool {
            false
        }

        fn format(&self, diag: &JCDiagnostic, locale: Option<&Locale>) -> String {
            let locale = locale.cloned().unwrap_or_else(Locale::default_locale);
            format!(
                "{}: {}",
                self.format_kind(diag, &locale),
                self.format_message(diag, &locale)
            )
        }

        fn format_message(&self, diag: &JCDiagnostic, locale: &Locale) -> String {
            let info = diag.get_diagnostic_info();
            let args: Vec<String> = info
                .get_args()
                .iter()
                .map(|arg| match java_string_of(arg) {
                    Some(text) => text,
                    None => "?".to_string(),
                })
                .collect();
            self.messages
                .get_localized_string_for(Some(locale), &info.key(), &args)
        }

        fn format_kind(&self, diag: &JCDiagnostic, _locale: &Locale) -> String {
            match diag.get_type() {
                DiagnosticType::ERROR => "error".to_string(),
                DiagnosticType::WARNING => "warning".to_string(),
                DiagnosticType::NOTE => "note".to_string(),
                DiagnosticType::FRAGMENT => "fragment".to_string(),
            }
        }

        fn format_source(&self, _diag: &JCDiagnostic, fullname: bool, _locale: &Locale) -> String {
            if fullname { "full" } else { "short" }.to_string()
        }

        fn format_position(
            &self,
            _diag: &JCDiagnostic,
            pk: PositionKind,
            _locale: &Locale,
        ) -> String {
            format!("{pk:?}")
        }

        fn get_configuration(&mut self) -> &mut dyn Configuration {
            &mut self.configuration
        }
    }

    fn test_messages() -> Rc<JavacMessages> {
        Rc::new(JavacMessages::new(crate::util::javac_messages::DEFAULT_BUNDLE_NAME))
    }

    fn factory() -> Factory {
        Factory::new(test_messages(), "compiler")
    }

    fn factory_with_formatter() -> Factory {
        let messages = test_messages();
        let formatter = Rc::new(MessagesFormatter::new(messages.clone()));
        Factory::new_with_formatter(messages, "compiler", formatter)
    }

    #[test]
    fn diagnostic_type_keys() {
        assert_eq!(DiagnosticType::FRAGMENT.key(), "misc");
        assert_eq!(DiagnosticType::NOTE.key(), "note");
        assert_eq!(DiagnosticType::WARNING.key(), "warn");
        assert_eq!(DiagnosticType::ERROR.key(), "err");
    }

    #[test]
    fn diagnostic_info_key_and_args() {
        let info = DiagnosticInfo::of(
            DiagnosticType::ERROR,
            "compiler",
            "cannot.resolve.sym",
            vec![string_arg("foo")],
        );
        assert_eq!(info.key(), "compiler.err.cannot.resolve.sym");
        assert_eq!(info.get_code(), "cannot.resolve.sym");
        assert_eq!(info.get_type(), DiagnosticType::ERROR);
        assert_eq!(info.get_prefix(), "compiler");
        assert_eq!(info.get_args().len(), 1);
        assert_eq!(java_string_of(&info.get_args()[0]).as_deref(), Some("foo"));
        let mut info = info;
        info.set_args(Vec::new());
        assert!(info.get_args().is_empty());
    }

    #[test]
    fn simple_diagnostic_position() {
        let position = SimpleDiagnosticPosition::new(7);
        assert_eq!(position.get_tree(), None);
        assert_eq!(position.get_start_position(), 7);
        assert_eq!(position.get_preferred_position(), 7);
        assert_eq!(position.get_end_position(None), 7);
        let table = MapEndPosTable;
        assert_eq!(position.get_end_position(Some(&table)), 7);
    }

    #[test]
    fn tree_diagnostic_position_uses_end_pos_table_fallback() {
        let position = TreeDiagnosticPosition {
            tree: TreeId::new(3),
            start: 1,
            preferred: 5,
            end: 9,
        };
        assert_eq!(position.get_tree(), Some(TreeId::new(3)));
        assert_eq!(position.get_end_position(None), 5);
        let table = MapEndPosTable;
        assert_eq!(position.get_end_position(Some(&table)), 9);
    }

    #[test]
    fn factory_creates_typed_keys() {
        let factory = factory();
        let error = factory.error_key("test.error", vec![string_arg("a")]);
        assert_eq!(error.info().get_type(), DiagnosticType::ERROR);
        assert_eq!(error.info().key(), "compiler.err.test.error");
        let warning = factory.warning_key("test.warning", Vec::new());
        assert_eq!(warning.info().get_type(), DiagnosticType::WARNING);
        let note = factory.note_key("test.note", Vec::new());
        assert_eq!(note.info().get_type(), DiagnosticType::NOTE);
        let fragment = factory.fragment_key("test.fragment", Vec::new());
        assert_eq!(fragment.info().get_type(), DiagnosticType::FRAGMENT);
        assert_eq!(fragment.info().key(), "compiler.misc.test.fragment");
    }

    #[test]
    fn factory_classification_and_mandatory_flags() {
        let factory = factory();
        let error = factory.error(None, None, None, factory.error_key("e", Vec::new()));
        assert_eq!(error.get_kind(), DiagnosticKind::ERROR);
        assert!(error.is_mandatory());

        let warning = factory.warning(None, None, None, factory.warning_key("w", Vec::new()));
        assert_eq!(warning.get_kind(), DiagnosticKind::WARNING);
        assert!(!warning.is_mandatory());

        let mandatory_warning = factory.mandatory_warning(
            None,
            None,
            None,
            factory.warning_key("mw", Vec::new()),
        );
        assert_eq!(
            mandatory_warning.get_kind(),
            DiagnosticKind::MANDATORY_WARNING
        );
        assert!(mandatory_warning.is_mandatory());

        let note = factory.mandatory_note(None, factory.note_key("n", Vec::new()));
        assert_eq!(note.get_kind(), DiagnosticKind::NOTE);
        assert!(note.is_mandatory());

        let fragment = factory.fragment(factory.fragment_key("f", Vec::new()));
        assert_eq!(fragment.get_kind(), DiagnosticKind::OTHER);
        assert!(!fragment.is_mandatory());
    }

    #[test]
    fn set_flag_applies_recoverable_semantics() {
        let factory = factory();
        let mut error = factory.error(None, None, None, factory.error_key("e", Vec::new()));
        error.set_flag(DiagnosticFlag::RECOVERABLE);
        assert!(error.is_flag_set(DiagnosticFlag::RECOVERABLE));
        error.set_flag(DiagnosticFlag::SYNTAX);
        assert!(error.is_flag_set(DiagnosticFlag::SYNTAX));
        assert!(!error.is_flag_set(DiagnosticFlag::RECOVERABLE));

        let mut error = factory.error(None, None, None, factory.error_key("e2", Vec::new()));
        error.set_flag(DiagnosticFlag::RESOLVE_ERROR);
        assert!(error.is_flag_set(DiagnosticFlag::RESOLVE_ERROR));
        assert!(error.is_flag_set(DiagnosticFlag::RECOVERABLE));
    }

    #[test]
    fn lint_category_is_kept() {
        let factory = factory();
        let lint = LintCategory::DEPRECATION;
        let warning = factory.warning(
            Some(lint),
            None,
            None,
            factory.warning_key("deprecat", Vec::new()),
        );
        assert!(warning.has_lint_category());
        assert_eq!(warning.get_lint_category(), Some(&lint));
        assert_eq!(lint.option(), "deprecation");

        let plain = factory.warning(None, None, None, factory.warning_key("w", Vec::new()));
        assert!(!plain.has_lint_category());
        assert_eq!(plain.get_lint_category(), None);
    }

    #[test]
    fn position_accessors() {
        let factory = factory();
        // A non-NOPOS position requires a source (upstream IllegalArgumentException
        // check); NO_SOURCE satisfies it and reports line/column 0 like the
        // upstream no-source DiagnosticSource.
        let source: Rc<crate::util::diagnostic_source::DiagnosticSource> =
            Rc::new(crate::util::diagnostic_source::DiagnosticSource::no_source());
        let position: Rc<dyn DiagnosticPosition> = Rc::new(SimpleDiagnosticPosition::new(7));
        let error = factory.error(
            None,
            Some(source),
            Some(position),
            factory.error_key("e", Vec::new()),
        );
        assert_eq!(error.get_int_start_position(), 7);
        assert_eq!(error.get_int_position(), 7);
        assert_eq!(error.get_int_end_position(), 7);
        assert_eq!(error.get_start_position(), 7);
        assert_eq!(error.get_position(), 7);
        assert_eq!(error.get_end_position(), 7);
        assert!(error.get_diagnostic_position().is_some());
        assert_eq!(error.get_line_number(), 0);
        assert_eq!(error.get_column_number(), 0);

        let no_position = factory.error(None, None, None, factory.error_key("e", Vec::new()));
        assert_eq!(no_position.get_int_start_position(), NOPOS);
        assert_eq!(no_position.get_position(), NOPOS as i64);
    }

    #[test]
    fn formatter_integration_uses_javac_messages_and_message_format() {
        let factory = factory_with_formatter();
        let error = factory.error(
            None,
            None,
            None,
            factory.error_key(
                "abstract.cant.be.instantiated",
                vec![string_arg("X")],
            ),
        );
        assert_eq!(error.get_prefix(), "error");
        assert_eq!(
            error.get_code_string(),
            "compiler.err.abstract.cant.be.instantiated"
        );
        let message = error.get_message(None);
        assert_eq!(message.to_string_lossy(), "X is abstract; cannot be instantiated");
        assert_eq!(
            error.format_diagnostic(),
            "error: X is abstract; cannot be instantiated"
        );
        assert_eq!(
            error.to_string(),
            "error: X is abstract; cannot be instantiated"
        );
        assert!(error.get_formatter().is_some());
    }

    #[test]
    fn fragment_arguments_are_normalized_to_diagnostics() {
        let factory = factory();
        let fragment_key = factory.fragment_key("test.fragment", vec![string_arg("f")]);
        let error = factory.create(
            DiagnosticType::ERROR,
            None,
            None,
            "test.error",
            vec![Rc::new(fragment_key.clone()) as DiagnosticArg],
        );
        assert_eq!(error.get_args().len(), 1);
        assert!(error.get_args()[0].downcast_ref::<JCDiagnostic>().is_some());
        assert!(error.get_args()[0].downcast_ref::<Fragment>().is_none());
    }

    #[test]
    fn multiline_diagnostic_keeps_inner_identity() {
        let factory = factory();
        let first = factory.error(None, None, None, factory.error_key("e", Vec::new()));
        let sub = factory.note(None, None, factory.note_key("n", Vec::new()));
        let multiline = MultilineDiagnostic::new(&first, List::of(sub.clone()));
        assert!(multiline.is_multiline());
        assert_eq!(multiline.get_subdiagnostics().length(), 1);
        assert_eq!(multiline.as_diagnostic().get_code_string(), "compiler.err.e");
        assert_eq!(
            multiline.as_diagnostic().get_kind(),
            DiagnosticKind::ERROR
        );
    }

    #[test]
    fn diagnostic_trait_implementation() {
        let factory = factory_with_formatter();
        let diag = factory.error(
            None,
            None,
            None,
            factory.error_key("abstract.cant.be.instantiated", vec![string_arg("X")]),
        );
        let diagnostic: &dyn Diagnostic<Rc<dyn JavaFileObject>> = &diag;
        assert_eq!(diagnostic.get_kind(), DiagnosticKind::ERROR);
        assert_eq!(diagnostic.get_position(), NOPOS as i64);
        assert!(diagnostic.get_source().is_none());
        assert_eq!(
            diagnostic
                .get_code()
                .expect("code")
                .to_string_lossy(),
            "compiler.err.abstract.cant.be.instantiated"
        );
        assert_eq!(
            diagnostic
                .get_message(Some(&tag("en")))
                .to_string_lossy(),
            "X is abstract; cannot be instantiated"
        );
    }

    #[test]
    fn contract_bridge_keeps_placeholder_arguments() {
        let factory = factory();
        let contract_error = compiler_errors::abstract_cant_be_instantiated(
            contract::SymbolArg::from("X"),
        );
        let error = factory.error(None, None, None, Error::from(contract_error));
        assert_eq!(
            error.get_code_string(),
            "compiler.err.abstract.cant.be.instantiated"
        );
        assert_eq!(error.get_args().len(), 1);
        assert_eq!(
            java_string_of(&error.get_args()[0]).as_deref(),
            Some("X")
        );
    }

    #[test]
    fn factory_instance_is_cached_in_context() {
        let mut context = Context::new();
        let first = Factory::instance(&mut context);
        let second = Factory::instance(&mut context);
        assert!(Rc::ptr_eq(&first, &second));
        assert_eq!(first.get_prefix(), "compiler");
    }
}
